<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('INSERT INTO medications(name,unit,stock_qty,unit_price,reorder_level) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['unit']),max(0,(float)$_POST['stock_qty']),(float)$_POST['unit_price'],max(0,(float)$_POST['reorder_level'])]);flash('Medicine added.');redirect('pharmacy.php');}$rows=$pdo->query('SELECT * FROM medications ORDER BY name')->fetchAll();$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();admin_header('Pharmacy','pharmacy.php');?><div class="pagehead"><div><h1>Pharmacy</h1><div class="muted">Medicine catalogue, stock levels and dispensing preparation.</div></div><a class="btn" href="?action=new">Add medicine</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Medicine</label><input name="name" required></div><div class="field"><label>Unit</label><input name="unit" value="tablet"></div><div class="field"><label>Stock quantity</label><input type="number" step="0.01" name="stock_qty" value="0"></div><div class="field"><label>Unit price (UGX)</label><input type="number" step="0.01" name="unit_price" value="0"></div><div class="field"><label>Reorder level</label><input type="number" step="0.01" name="reorder_level" value="0"></div></div><button style="margin-top:14px">Save medicine</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Medicine</th><th>Unit</th><th>Stock</th><th>Price</th><th>Reorder</th><th>Flag</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['unit'])?></td><td><?=e($r['stock_qty'])?></td><td>UGX <?=number_format((float)$r['unit_price'],0)?></td><td><?=e($r['reorder_level'])?></td><td><?=($r['stock_qty']<=$r['reorder_level']?'<span class="badge warn">Low stock</span>':'<span class="badge ok">OK</span>')?></td></tr><?php endforeach;?></table></div><?php admin_footer();
